def is_clean_palindrome(text):
    clean = [c.lower() for c in text if c.isalnum()]
    return clean == clean[::-1]

def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        need = target - x
        if need in seen:
            return [seen[need], i]
        seen[x] = i

def merge_intervals(intervals):
    if not intervals:
        return []
    items = sorted(intervals)
    out = [items[0][:]]
    for start, end in items[1:]:
        if start <= out[-1][1]:
            out[-1][1] = max(out[-1][1], end)
        else:
            out.append([start, end])
    return out

def first_occurrence(nums, target):
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo if lo < len(nums) and nums[lo] == target else -1

def longest_unique_length(s):
    last = {}
    left = 0
    best = 0
    for right, ch in enumerate(s):
        if ch in last and last[ch] >= left:
            left = last[ch] + 1
        last[ch] = right
        best = max(best, right - left + 1)
    return best

def edit_distance(a, b):
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            cur.append(prev[j-1] if ca == cb else 1 + min(prev[j], cur[j-1], prev[j-1]))
        prev = cur
    return prev[-1]

def max_weight_nonoverlap(jobs):
    items = sorted(jobs, key=lambda x: x[1])
    ends = [x[1] for x in items]
    dp = [0] * (len(items) + 1)
    for i, (start, end, weight) in enumerate(items, 1):
        lo, hi = 0, i - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if ends[mid] <= start:
                lo = mid + 1
            else:
                hi = mid
        compatible = lo if lo < i - 1 and ends[lo] <= start else lo - 1
        dp[i] = max(dp[i-1], weight + dp[compatible + 1])
    return dp[-1]

def min_cover(s, t):
    if not t:
        return ''
    need = {}
    for c in t:
        need[c] = need.get(c, 0) + 1
    have = {}
    formed = 0
    left = 0
    best = (len(s) + 1, 0, 0)
    for right, c in enumerate(s):
        have[c] = have.get(c, 0) + 1
        if c in need and have[c] == need[c]:
            formed += 1
        while formed == len(need):
            if right - left + 1 < best[0]:
                best = (right - left + 1, left, right + 1)
            d = s[left]
            have[d] -= 1
            if d in need and have[d] < need[d]:
                formed -= 1
            left += 1
    return '' if best[0] > len(s) else s[best[1]:best[2]]
